int skip_id3_tag(SF_PRIVATE *psf) {
    unsigned char header[10];
    int result = 0;
    long file_length;

    // Check if the file is valid
    if (!psf || !psf->file || psf->file_length <= 0)
        return 0;

    // Read the first 10 bytes of the ID3 tag
    if (fread(header, sizeof(unsigned char), 10, psf->file) != 10)
        return 0;

    // Check if it is an ID3 tag
    if (header[0] == 'I' && header[1] == 'D' && header[2] == '3') {
        // Calculate the size of the tag (7th to 10th bytes are the size)
        long tag_size = ((header[6] & 0x7F) << 21) |
                         ((header[7] & 0x7F) << 14) |
                         ((header[8] & 0x7F) << 7) |
                          (header[9] & 0x7F);

        // Add the 10 bytes read to the tag size to get the total size
        tag_size += 10;

        // Update the file offset
        if (fseek(psf->file, tag_size, SEEK_SET) != 0)
            return 0;

        // Update the file length to exclude the ID3 tag
        file_length = psf->file_length - tag_size;
        if (file_length < 0)
            file_length = 0;

        psf->file_length = file_length;
        result = 1;
    }

    return result;
}

int skip_id3_tag(SF_PRIVATE *psf) {
    uint8_t header[10];
    int64_t tag_size;

    if (fread(header, sizeof(uint8_t), 10, psf->file) != 10)
        return 0;

    if (header[0] != 'I' || header[1] != 'D' || header[2] != '3')
        return 0;

    tag_size = (header[6] << 21) | (header[7] << 14) | (header[8] << 7) | header[9];
    tag_size += 10;

    if (tag_size > psf->filelength)
        return 0;

    if (fseek(psf->file, tag_size, SEEK_SET) != 0)
        return 0;

    psf->fileoffset = tag_size;
    return 1;
}

int skip_id3_tag(SF_PRIVATE *psf)
{
    sf_count_t file_length;
    sf_count_t offset;
    char header[10];

    if (psf->file.format & SF_FORMAT_ID3)
        return 1;

    if (psf_fread(header, 1, 10, psf) != 10)
        return 0;

    if (memcmp(header, "ID3", 3) != 0)
        return 0;

    offset = ((header[6] & 0x7F) << 21) | ((header[7] & 0x7F) << 14) |
             ((header[8] & 0x7F) << 7) | (header[9] & 0x7F);

    file_length = psf_get_filelen(psf);

    if (offset >= file_length)
        return 0;

    psf->file.dataoffset = offset;
    psf->file.format |= SF_FORMAT_ID3;

    return 1;
}

int skip_id3_tag(SF_PRIVATE *psf) {
    unsigned char id3_header[10];
    int32_t tag_size;

    if (psf->filelength < 10)
        return 0;

    if (sf_readf_bytes(psf, id3_header, 10) != 10)
        return 0;

    if (memcmp(id3_header, "ID3", 3) != 0)
        return 1;

    tag_size = (id3_header[6] & 0x7F) << 21;
    tag_size |= (id3_header[7] & 0x7F) << 14;
    tag_size |= (id3_header[8] & 0x7F) << 7;
    tag_size |= (id3_header[9] & 0x7F);

    tag_size += 10;

    if (tag_size > psf->filelength)
        return 0;

    psf->fileoffset[0] = tag_size;
    psf->dataoffset = tag_size;

    return 1;
}

int skip_id3_tag(SF_PRIVATE *psf) {
    unsigned char header[10];

    if (psf->filelength < 10)
        return 0;

    if (sf_readf_bytes(psf, header, 10) != 10)
        return 0;

    if (header[0] != 'I' || header[1] != 'D' || header[2] != '3')
        return 0;

    int size = ((header[6] & 0x7f) << 21) | ((header[7] & 0x7f) << 14) |
               ((header[8] & 0x7f) << 7) | (header[9] & 0x7f);
    psf->fileoffset += 10 + size;

    if (psf->fileoffset > psf->filelength)
        psf->fileoffset = psf->filelength;

    return 1;
}
